mapper.select:
select w.id, w.question_id as questionId, w.wrong_count as wrongCount, w.mastered,
       w.last_wrong_time as lastWrongTime, w.last_answer as lastAnswer,
       q.stem, q.type, q.difficulty, q.analysis, q.answer as referenceAnswer,
       k.name as knowledgePointName
from wrong_question w
         join question q on q.id = w.question_id
         left join knowledge_point k on k.id = q.knowledge_point_id
where w.user_id = #{userId}
 and w.mastered = #{mastered} 
 and q.knowledge_point_id = #{knowledgePointId} 
order by w.last_wrong_time desc
limit #{limit}
